// 1. Reynolds number: inertial to viscous force ratio
val diameterM = cylinderDiameterMm * 1e-3f
val reynolds = (fluidDensityKgM3 * flowVelocityMS * diameterM) / max(fluidViscosityPaS, 1e-7f)

// 2. Strouhal shedding frequency
val strouhal = 0.198f * (1f - (19.7f / max(reynolds, 20f)))
val sheddingFrequencyHz = strouhal * (flowVelocityMS / max(diameterM, 1e-5f))
